import React, { useState, useEffect } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { ordersApi, reviewsApi } from '../services/api';

const MyOrders = () => {
    const navigate = useNavigate();
    const [myOrders, setMyOrders] = useState([]);

    // State quản lý Popup Đánh giá
    const [showReviewModal, setShowReviewModal] = useState(false);
    const [selectedOrderDetails, setSelectedOrderDetails] = useState(null); // Lưu thông tin đơn đang đánh giá
    const [reviewData, setReviewData] = useState({}); // Lưu dữ liệu đánh giá của từng sản phẩm

    const statusMap = {
        "Pending": { label: "Chờ xử lý", color: "bg-secondary" },
        "Processing": { label: "Chờ vận chuyển", color: "bg-info" },
        "Shipping": { label: "Đang giao hàng", color: "bg-warning" },
        "Completed": { label: "Đã giao thành công", color: "bg-success" },
        "Cancelled": { label: "Đã hủy", color: "bg-danger" }
    };

    useEffect(() => {
        const userData = JSON.parse(localStorage.getItem('user') || '{}');
        const currentUserId = userData.userId || userData.id;

        if (!currentUserId) {
            navigate('/login');
            return;
        }

        ordersApi.getByUserId(currentUserId)
            .then(res => setMyOrders(res.data || []))
            .catch(err => console.log("Lỗi tải lịch sử đơn hàng: ", err));
    }, [navigate]);

    // HÀM MỞ POPUP ĐÁNH GIÁ SẢN PHẨM CỦA 1 ĐƠN HÀNG
    const handleOpenReview = async (order) => {
        try {
            // Lấy chi tiết đơn hàng để biết mua những sản phẩm gì
            const res = await ordersApi.getById(order.id);
            const details = res.data.details || res.data;
            setSelectedOrderDetails({ orderId: order.id, items: details });

            // Khởi tạo state trắng cho từng sản phẩm
            const initialReviewState = {};
            details.forEach(item => {
                initialReviewState[item.productId] = { rating: 5, comment: '', imageFile: null };
            });
            setReviewData(initialReviewState);
            setShowReviewModal(true);
        } catch (error) {
            alert("Lỗi không lấy được chi tiết đơn hàng!");
        }
    };

    // HÀM CẬP NHẬT DỮ LIỆU KHI KHÁCH GÕ VÀO FORM (Cho từng sản phẩm riêng biệt)
    const handleReviewChange = (productId, field, value) => {
        setReviewData(prev => ({
            ...prev,
            [productId]: { ...prev[productId], [field]: value }
        }));
    };

    // HÀM GỬI ĐÁNH GIÁ TỪNG SẢN PHẨM LÊN C# BẰNG FORMDATA (Để up ảnh)
    const handleSubmitSingleReview = async (productId) => {
        const data = reviewData[productId];
        if (!data.comment) {
            alert("Ní vui lòng nhập chút nhận xét nha!");
            return;
        }

        const userData = JSON.parse(localStorage.getItem('user') || '{}');

        // Dùng FormData thay vì JSON để có thể gửi File ảnh
        const formData = new FormData();
        formData.append('OrderId', selectedOrderDetails.orderId);
        formData.append('ProductId', productId);
        formData.append('UserId', userData.userId || userData.id);
        formData.append('UserName', userData.name || userData.userName || 'Khách hàng');
        formData.append('Rating', data.rating);
        formData.append('Comment', data.comment);
        if (data.imageFile) {
            formData.append('ImageFile', data.imageFile); // Đính kèm file ảnh
        }

        try {
            await reviewsApi.submitReview(formData);
            alert("Gửi đánh giá thành công! 🌟");
            // Tạm thời tắt review cho sp này trên giao diện (Đã đánh giá xong)
            handleReviewChange(productId, 'submitted', true);
        } catch (error) {
            console.error(error);
            alert("Lỗi kết nối Backend. Ní kiểm tra C# nha!");
        }
    };

    return (
        <>
            <div className="container-fluid page-header py-5">
                <h1 className="text-center text-white display-6">Lịch Sử Mua Hàng</h1>
            </div>

            <div className="container-fluid py-5">
                <div className="container py-5">
                    <div className="table-responsive">
                        <table className="table table-hover align-middle text-center">
                            <thead className="table-dark">
                                <tr>
                                    <th>Mã đơn</th>
                                    <th>Ngày đặt</th>
                                    <th>Tổng tiền</th>
                                    <th>Trạng thái</th>
                                    <th>Thao tác</th>
                                </tr>
                            </thead>
                            <tbody>
                                {myOrders.map((order) => (
                                    <tr key={order.id}>
                                        <td className="fw-bold text-primary">#{order.id}</td>
                                        <td>{new Date(order.orderDate || order.createdAt).toLocaleDateString('vi-VN')}</td>
                                        <td className="fw-bold">${order.totalAmount?.toFixed(2)}</td>
                                        <td>
                                            <span className={`badge ${statusMap[order.status]?.color || 'bg-secondary'} p-2 rounded-pill`}>
                                                {statusMap[order.status]?.label || order.status}
                                            </span>
                                        </td>
                                        <td>
                                            {/* NẾU ĐƠN HOÀN THÀNH (Completed) THÌ HIỆN NÚT ĐÁNH GIÁ */}
                                            {order.status === "Completed" && (
                                                <button
                                                    className="btn btn-sm btn-outline-warning rounded-pill"
                                                    onClick={() => handleOpenReview(order)}
                                                >
                                                    <i className="fa fa-star me-1"></i>Đánh giá SP
                                                </button>
                                            )}
                                        </td>
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </div>
                </div>
            </div>

            {/* MODAL ĐÁNH GIÁ TỪNG SẢN PHẨM TRONG ĐƠN HÀNG */}
            {showReviewModal && selectedOrderDetails && (
                <div className="modal fade show d-block" style={{ backgroundColor: 'rgba(0,0,0,0.5)', overflowY: 'auto' }}>
                    <div className="modal-dialog modal-lg modal-dialog-centered">
                        <div className="modal-content">
                            <div className="modal-header bg-primary text-white">
                                <h5 className="modal-title">Đánh giá Đơn hàng #{selectedOrderDetails.orderId}</h5>
                                <button type="button" className="btn-close btn-close-white" onClick={() => setShowReviewModal(false)}></button>
                            </div>
                            <div className="modal-body p-4">
                                {selectedOrderDetails.items.map(item => {
                                    const rData = reviewData[item.productId] || {};
                                    return (
                                        <div key={item.productId} className="border rounded p-3 mb-4 bg-light">
                                            <div className="d-flex align-items-center mb-3">
                                                <div className="fw-bold text-dark fs-5">Mã SP: {item.productId}</div>
                                            </div>

                                            {rData.submitted ? (
                                                <div className="alert alert-success text-center">Ní đã đánh giá sản phẩm này rồi! Cảm ơn ní nha! 💖</div>
                                            ) : (
                                                <div className="row g-3">
                                                    <div className="col-12 d-flex align-items-center">
                                                        <label className="me-3 fw-bold">Chất lượng:</label>
                                                        {[1, 2, 3, 4, 5].map(star => (
                                                            <i key={star}
                                                                className={`fa fa-star fs-4 ${star <= (rData.rating || 5) ? 'text-warning' : 'text-secondary'}`}
                                                                style={{ cursor: 'pointer' }}
                                                                onClick={() => handleReviewChange(item.productId, 'rating', star)}
                                                            ></i>
                                                        ))}
                                                    </div>

                                                    <div className="col-12">
                                                        <textarea
                                                            className="form-control"
                                                            rows="3"
                                                            placeholder="Mô tả trải nghiệm của ní về sản phẩm này..."
                                                            value={rData.comment}
                                                            onChange={(e) => handleReviewChange(item.productId, 'comment', e.target.value)}
                                                        ></textarea>
                                                    </div>

                                                    <div className="col-12">
                                                        <label className="fw-bold mb-2">Thêm hình ảnh thực tế (Không bắt buộc):</label>
                                                        <input
                                                            type="file"
                                                            className="form-control"
                                                            accept="image/*"
                                                            onChange={(e) => handleReviewChange(item.productId, 'imageFile', e.target.files[0])}
                                                        />
                                                    </div>

                                                    <div className="col-12 text-end mt-3">
                                                        <button
                                                            className="btn btn-warning px-4 rounded-pill text-white fw-bold"
                                                            onClick={() => handleSubmitSingleReview(item.productId)}
                                                        >
                                                            Gửi Đánh Giá
                                                        </button>
                                                    </div>
                                                </div>
                                            )}
                                        </div>
                                    )
                                })}
                            </div>
                        </div>
                    </div>
                </div>
            )}
        </>
    );
};

export default MyOrders;
